/* ibverbs.map -- export the shim's verbs under the symbol VERSIONS NCCL asks
 * for, because NCCL does not use dlsym.
 *
 * src/misc/ibvsymbols.cc (v2.32.6-1, sha256 ea1c4825918f5eb4) builds its verbs
 * table with
 *
 *     #define IBVERBS_VERSION "IBVERBS_1.1"
 *     tmp = dlvsym(handle, symbol, IBVERBS_VERSION);
 *     if (tmp == NULL) { WARN("dlvsym failed on %s ..."); goto teardown; }
 *
 * and teardown NULLs the whole table.  An unversioned symbol makes dlvsym
 * return NULL, so NCCL reported
 *
 *     NCCL WARN dlvsym failed on ibv_get_device_list - .../libibverbs.so:
 *     undefined symbol: ibv_get_device_list, version IBVERBS_1.1
 *
 * and fell back to "Using network Socket" -- with a perfectly working shim
 * underneath.  That is why arm (a) is a versioning problem, not a verbs
 * problem, and it is measured rather than assumed: dlvsym_probe.c asks for
 * exactly the pairs below.
 *
 * The mandatory list is the LOAD_SYM() block (version IBVERBS_1.1); the rest
 * are LOAD_SYM_VERSION() cherry-picks whose failure is silent, but a dmabuf
 * registration is arm (c), so ibv_reg_dmabuf_mr must be there under 1.12.
 *
 * No `local: *;`: symbols not named here (ibv_create_ah, ibv_post_send,
 * fakeib_* counters, ...) keep their base version and stay global, which the
 * CPU-side probes link against.
 */
IBVERBS_1.1 {
    global:
        ibv_get_device_list;
        ibv_free_device_list;
        ibv_get_device_name;
        ibv_open_device;
        ibv_close_device;
        ibv_get_async_event;
        ibv_ack_async_event;
        ibv_query_device;
        ibv_query_port;
        ibv_query_gid;
        ibv_query_pkey;
        ibv_query_qp;
        ibv_alloc_pd;
        ibv_dealloc_pd;
        ibv_reg_mr;
        ibv_dereg_mr;
        ibv_create_cq;
        ibv_destroy_cq;
        ibv_create_qp;
        ibv_modify_qp;
        ibv_destroy_qp;
        ibv_fork_init;
        ibv_event_type_str;
};

IBVERBS_1.8 {
    global:
        ibv_reg_mr_iova2;
};

IBVERBS_1.10 {
    global:
        ibv_query_ece;
        ibv_set_ece;
};

IBVERBS_1.12 {
    global:
        ibv_reg_dmabuf_mr;
};

IBVERBS_1.16 {
    global:
        ibv_query_port_speed;
};
